-- GenDB engine variant Q02-commuted_comparisons: template q02.sql, kind commuted_comparisons (generated by generate.py; frozen)
SELECT
  s_acctbal,
  s_name,
  n_name,
  p_partkey,
  p_mfgr,
  s_address,
  s_phone,
  s_comment
FROM part, supplier, partsupp, nation, region
WHERE
  ps_partkey = p_partkey
  AND ps_suppkey = s_suppkey
  AND $1 = p_size
  AND p_type LIKE $2
  AND n_nationkey = s_nationkey
  AND r_regionkey = n_regionkey
  AND $3 = r_name
  AND (
    SELECT
      MIN(ps_supplycost)
    FROM partsupp, supplier, nation, region
    WHERE
      ps_partkey = p_partkey
      AND ps_suppkey = s_suppkey
      AND n_nationkey = s_nationkey
      AND r_regionkey = n_regionkey
      AND $3 = r_name
  ) = ps_supplycost
ORDER BY
  s_acctbal DESC,
  n_name,
  s_name,
  p_partkey
LIMIT 100
